"""Keep the suite's executable dependencies local after relocation."""

from __future__ import annotations

import os
from pathlib import Path


suite_root = Path(__file__).resolve().parents[4]
ffmpeg_bin = suite_root / "dependencies" / "ffmpeg" / "bin"
os.environ["PATH"] = f"{ffmpeg_bin}{os.pathsep}{os.environ.get('PATH', '')}"
os.environ["MONTAGE_FFMPEG"] = str(ffmpeg_bin / "ffmpeg.exe")
os.environ["MONTAGE_FFPROBE"] = str(ffmpeg_bin / "ffprobe.exe")
